import type { ParsedSourceMetadata } from './source-parser.js';
import { slugifyTitle } from '@scooper/exporters';

const REPAIR_SESSION_NOTE =
  'Generated by KAE Repository Repair because source KRC existed without matching executive session.';

/** Builds a placeholder executive session from an existing source file. */
export function buildRepairExecutiveSessionMarkdown(
  krcId: string,
  sourceRelativePath: string,
  parsed: ParsedSourceMetadata,
  repairNote: string = REPAIR_SESSION_NOTE,
): string {
  const title = parsed.title;
  const sessionDate = parsed.createTime ?? new Date().toISOString().slice(0, 10);

  return [
    `# Executive Session Record — ${title}`,
    '',
    '## Source ID',
    krcId,
    '',
    '## Session Date',
    sessionDate,
    '',
    '## Classification',
    `- Primary: ${parsed.primaryProduct}`,
    `- Status: ${parsed.status}`,
  '',
    '## Session Summary',
    `Placeholder executive session generated from source record ${krcId}.`,
    `Topic: ${parsed.topic}`,
    '',
    '## Key Topics',
    `- ${parsed.topic}`,
    '',
    '## Action / Follow-up',
    'Review source transcript and complete capability extraction when ready.',
    '',
    '## Transcript Reference',
    sourceRelativePath,
    '',
    '## Notes',
    repairNote,
    `Generated on ${new Date().toISOString().slice(0, 10)}.`,
  ].join('\n');
}

/** Builds executive session filename from KRC ID and title. */
export function buildRepairSessionFilename(krcId: string, title: string): string {
  return `${krcId}_${slugifyTitle(title)}_SESSION.md`;
}

/** Builds source filename from KRC ID and title. */
export function buildRepairSourceFilename(krcId: string, title: string): string {
  return `${krcId}_${slugifyTitle(title)}.md`;
}

export const DUPLICATE_REPAIR_NOTE = (oldId: string, newId: string, date: string): string =>
  `Reassigned from ${oldId} to ${newId} by KAE Repository Repair on ${date}. ` +
  `Canonical record retains ${oldId}; this duplicate was preserved with a new ID.`;
